//! Freshness of the WASM runner's vector index, `tests/vectors/mod.rs` (0006 T02).
//!
//! The wasm-bindgen-test runner (`tests/conformance.rs`) runs inside Node and Chrome, which have
//! no file system to walk, so it embeds every `conformance/vectors/**/*.json` with
//! `include_str!`, listed in a **generated** index. A build script would also work, but it would
//! run on every build of the adapter, including the shipped `wasm-pack build`, for the sake of a
//! test; a committed, generated file keeps the adapter's build exactly as it is. The price is that
//! a new vector file needs the index regenerated, and this host test makes that impossible to
//! miss: it walks `conformance/vectors/` recursively (conformance/README.md "Rules for every
//! runner": a glob of `vectors/**`, never a list of directories) and fails unless the index lists
//! exactly those files, in byte order of their `/`-separated paths, as the generator writes it.
//!
//! Regenerate with:
//!
//! ```text
//! POLYJOSE_WRITE_VECTOR_INDEX=1 cargo test -p polyjose-wasm --test vector_index
//! ```
//!
//! `bindings/wasm/test.sh` runs this test before the two wasm-pack runs.
#![cfg(not(target_arch = "wasm32"))]
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // test code: a panic is a failed assertion

use std::path::{Path, PathBuf};

/// The environment variable that makes the test write the index instead of only checking it.
const WRITE: &str = "POLYJOSE_WRITE_VECTOR_INDEX";

fn vectors_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../conformance/vectors")
}

fn index_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/vectors/mod.rs")
}

/// Every `*.json` file under `dir`, as `/`-separated paths relative to `root`. A symbolic link
/// or a name that isn't UTF-8 fails the test (as in the Rust runners: a vector is never dropped).
fn collect(root: &Path, dir: &Path, out: &mut Vec<String>) {
    let entries = std::fs::read_dir(dir).unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
    for entry in entries {
        let entry = entry.unwrap_or_else(|e| panic!("{}: {e}", dir.display()));
        let path = entry.path();
        let kind = entry
            .file_type()
            .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        if kind.is_symlink() {
            panic!("{}: a symbolic link under conformance/vectors", path.display());
        } else if kind.is_dir() {
            collect(root, &path, out);
        } else if path.extension().is_some_and(|ext| ext == "json") {
            let relative = path.strip_prefix(root).expect("below the root");
            let parts: Vec<&str> = relative
                .components()
                .map(|c| {
                    c.as_os_str()
                        .to_str()
                        .unwrap_or_else(|| panic!("{}: not UTF-8", path.display()))
                })
                .collect();
            out.push(parts.join("/"));
        }
    }
}

/// The index text for these vector paths.
fn index_text(paths: &[String]) -> String {
    let mut text = String::from(
        "// @generated by bindings/wasm/tests/vector_index.rs; do not edit. Regenerate with\n\
         // `POLYJOSE_WRITE_VECTOR_INDEX=1 cargo test -p polyjose-wasm --test vector_index`.\n\
         //! Every `conformance/vectors/**/*.json` file, embedded for the wasm-bindgen-test runner\n\
         //! (0006 T02): its path under `conformance/vectors/` and its text, in byte order of the\n\
         //! paths. `tests/vector_index.rs` fails when this list differs from the directory.\n\
         \n\
         /// `(path under conformance/vectors/, file text)` for every vector file.\n\
         #[rustfmt::skip]\n\
         pub(crate) const VECTORS: &[(&str, &str)] = &[\n",
    );
    for path in paths {
        assert!(
            !path.contains(['"', '\\']),
            "{path}: a vector path with a quote or backslash"
        );
        text.push_str(&format!(
            "    (\"{path}\", include_str!(\"../../../../conformance/vectors/{path}\")),\n"
        ));
    }
    text.push_str("];\n");
    text
}

#[test]
fn the_vector_index_lists_every_vector_file() {
    let root = vectors_dir();
    let mut paths = Vec::new();
    collect(&root, &root, &mut paths);
    paths.sort();
    assert!(!paths.is_empty(), "{}: no vector files", root.display());
    let want = index_text(&paths);
    let path = index_path();
    if std::env::var_os(WRITE).is_some_and(|v| v == "1") {
        std::fs::write(&path, &want).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
        eprintln!("wrote {} ({} vectors)", path.display(), paths.len());
    }
    let got = std::fs::read_to_string(&path).unwrap_or_default();
    assert!(
        got == want,
        "{} is stale: it does not list exactly the {} files under conformance/vectors/. \
         Regenerate it with `{WRITE}=1 cargo test -p polyjose-wasm --test vector_index`.",
        path.display(),
        paths.len()
    );
}
